// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.repositoryimport com.roshan.persona.brain.memory.FactSourceimport com.roshan.persona.brain.memory.UserFactimport com.roshan.persona.common.Resultimport com.roshan.persona.database.dao.UserFactDaoimport com.roshan.persona.database.entity.UserFactEntityimport timber.log.Timberimport java.time.Instantimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.AppError/** * NOUS — User Fact Repository. * * Stores facts about the user (name, preferences, skills, etc.). * Uses Bayesian confidence (alpha/beta) — alpha = confirmations, beta = contradictions. * Confidence = alpha / (alpha + beta). */class UserFactRepository(    private val dao: UserFactDao,) {    suspend fun getAll(): Result<List<UserFact>> {        return try {            val entities = dao.getAll()            Result.Success(entities.map { it.toUserFact() }, CorrelationId.generate(), 0)        } catch (e: Exception) {            Timber.e(e, "Failed to get user facts")            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    suspend fun store(key: String, value: String, source: FactSource): Result<Long> {        return try {            val existing = dao.getByKey(key)            if (existing != null) {                dao.reinforce(existing.id, System.currentTimeMillis())                Result.Success(existing.id, CorrelationId.generate(), 0)            } else {                val now = System.currentTimeMillis()                val entity = UserFactEntity(                    key = key,                    value = value,                    confidenceAlpha = 1.0f,                    confidenceBeta = 0.0f,                    source = source.name,                    learnedAt = now,                    lastConfirmed = now,                    isDeleted = false,                    createdAt = now,                    updatedAt = now,                )                val id = dao.insert(entity)                Result.Success(id, CorrelationId.generate(), 0)            }        } catch (e: Exception) {            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    suspend fun count(): Int = try { dao.count() } catch (e: Exception) { 0 }}private fun UserFactEntity.toUserFact(): UserFact {    val alpha = this.confidenceAlpha    val beta = this.confidenceBeta    val confidence = if (alpha + beta > 0) alpha / (alpha + beta) else 0f    return UserFact(        key = this.key,        value = this.value,        confidence = confidence,        source = runCatching { FactSource.valueOf(this.source) }.getOrDefault(FactSource.USER_EXPLICIT),        learnedAt = Instant.ofEpochMilli(this.learnedAt),    )}